vg_gain / avg_loss\n    return 100.0 - (100.0 / (1.0 + rs))\n\ndef calculate_macd_series(prices, short_period=12, long_period=26, signal_period=9):\n    """Calculates the MACD line, signal line, and histogram series."""\n    if len(prices) < long_period:\n        return None, None, None\n    short_ema_series = calculate_ema_series(prices, short_period)\n    long_ema_series = calculate_ema_series(prices, long_period)\n    macd_line = short_ema_series[len(short_ema_series)-len(long_ema_series):] - long_ema_series\n    if len(macd_line) < signal_period:\n        return macd_line, None, None\n    signal_line = calculate_ema_series(macd_line, signal_period)\n    histogram = macd_line[len(macd_line)-len(signal_line):] - signal_line\n    return macd_line, signal_line, histogram\n\ndef calculate_atr(prices, period=14):\n    """Calculates Average True Range (ATR) using close-to-close volatility."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    # For ATR, we need High, Low, Close. Since we only have Close, we approximate True Range\n    # as the absolute difference between consecutive closes.\n    # A more robust ATR would require daily HLC data.\n    price_ranges = np.abs(np.diff(prices_arr))\n    if len(price_ranges) < period: # Ensure enough data for EMA of ranges\n        return None\n    atr_series = calculate_ema_series(price_ranges, period)\n    return atr_series[-1] if len(atr_series) > 0 else None\n\ndef calculate_roc(prices, period=20):\n    """Calculates the Rate of Change (ROC) over a given period."""\n    if len(prices) < period + 1:\n        return None\n    return ((prices[-1] - prices[-1 - period]) / prices[-1 - period]) * 100\n\ndef decide(current_price, price_history, news_context):\n    """\n    SELF-IMPROVED STRATEGY V3:\n    This version refines the successful parent strategy with key enhancements based on\n    quantitative and qualitative feedback:\n    1.  Dynamic ATR-Based Stop-Loss: Replaces the fixed percentage stop-loss with a\n        volatility-adaptive ATR-based stop-loss to improve drawdown control and\n        adapt to changing market conditions.\n    2.  Refined Sentiment Permissiveness: Adjusts sentiment thresholds and neutralizes\n        ambiguous keywords ("strong jobs report") to reduce false signals and allow\n        technical indicators to drive decisions more effectively.\n    3.  Preservation of Core Strengths: Maintains the successful hierarchical regime\n        detection (Contrarian Capitulation, Crisis Aversion) and momentum velocity\n        confirmations (MACD histogram delta) that contributed to past outperformance.\n    """\n    # --- 1. Sentiment Analysis ---\n    context_lower = news_context.lower()\n    sentiment_keywords = {\n        "fed pivot": 3.0, "rate cut": 2.5, "quantitative easing": 2.5, "soft landing": 2.5,\n        "cooling inflation": 2.5, "cpi miss": 2.5, "ai boom": 2.5, "stimulus": 2.0,\n        "dovish": 2.0, "record high": 2.0, "bullish": 2.0, "strong earnings": 2.0,\n        "beat estimates": 1.5, "recovery": 1.5, "upgrade": 1.5, "de-escalation": 2.0,\n        "short squeeze": 3.5, "capitulation": 3.0, "panic selling": 2.5, "extreme fear": 2.0,\n        "strong jobs report": 0.0, # Neutralized: ambiguous market interpretation\n        "recession": -3.0, "crisis": -3.0, "stagflation": -3.0, "hot inflation": -3.0,\n        "war": -3.0, "yield curve inversion": -3.5, "quantitative tightening": -2.5,\n        "black swan": -4.0, "systemic risk": -4.0, "contagion": -3.5, "credit crunch": -3.5,\n        "rate hike": -2.5, "bankruptcy": -2.5, "hard landing": -2.5, "geopolitical risk": -2.5,\n        "cpi beat": -2.5, "vix spike": -2.5, "hawkish": -2.0, "bearish": -2.0,\n        "sell-off": -2.0, "weak earnings": -2.0, "market turmoil": -2.0, "bubble": -2.0,\n        "uncertainty": -1.5,\n        "euphoria": -2.5, "mania": -3.0, "irrational exuberance": -3.0, "extreme greed": -2.5,\n    }\n    negation_words = ["not", "no", "lack of", "fail to", "without", "struggle to", "avoids", "prevent"]\n    net_sentiment_score = 0.0\n    for keyword, weight in sentiment_keywords.items():\n        pattern = r'\\b' + re.escape(keyword) + r'\\b'\n        for match in re.finditer(pattern, context_lower):\n            pre_context = context_lower[max(0, match.start() - 30):match.start()]\n            is_negated = any(neg_word in pre_context for neg_word in negation_words)\n            net_sentiment_score += -weight if is_negated else weight\n\n    # --- 2. Technical Indicators & State Calculation ---\n    all_prices = price_history + [current_price]\n\n    # Indicator Periods\n    SMA_TREND_LONG = 100\n    SMA_TREND_MEDIUM = 50\n    RSI_PERIOD = 14\n    ATR_SHORT = 10 # Used for dynamic stop-loss\n    ATR_LONG = 50 # Used for volatility regime detection\n    ROC_CRASH_PERIOD = 20\n    STOP_LOSS_LOOKBACK = 20 # Period for recent high for stop-loss\n\n    required_history_length = max(SMA_TREND_LONG + 1, ATR_LONG + 1, ROC_CRASH_PERIOD + 1, STOP_LOSS_LOOKBACK + 1)\n    if len(all_prices) < required_history_length:\n        return "HOLD"\n\n    # Calculate core indicators\n    sma_100 = calculate_sma(all_prices, SMA_TREND_LONG)\n    sma_50 = calculate_sma(all_prices, SMA_TREND_MEDIUM)\n    rsi = calculate_rsi(all_prices, RSI_PERIOD)\n    _, _, macd_hist_series = calculate_macd_series(all_prices)\n    short_atr = calculate_atr(all_prices, ATR_SHORT)\n    long_atr = calculate_atr(all_prices, ATR_LONG)\n    roc_20 = calculate_roc(all_prices, ROC_CRASH_PERIOD)\n    donchian_high_20 = np.max(all_prices[-STOP_LOSS_LOOKBACK:]) if len(all_prices) >= STOP_LOSS_LOOKBACK else None\n\n    # Null check for all indicators\n    if any(v is None for v in [sma_100, sma_50, rsi, short_atr, long_atr, roc_20, donchian_high_20]) or macd_hist_series is None or len(macd_hist_series) < 2:\n        return "HOLD"\n\n    macd_histogram = macd_hist_series[-1]\n    prev_macd_histogram = macd_hist_series[-2]\n    macd_hist_delta = macd_histogram - prev_macd_histogram\n\n    # --- 3. Regime Detection ---\n    # Crisis Regime: General high-risk environment\n    is_long_term_downtrend = current_price < sma_100\n    is_high_volatility = short_atr > (long_atr * 1.75)\n    is_crash_velocity = roc_20 < -15.0\n    is_crisis_regime = (is_long_term_downtrend and is_high_volatility) or is_crash_velocity\n\n    # Capitulation Regime: An extreme subset of crisis, signaling a potential bottom\n    is_deeply_oversold = rsi < 25\n    is_extreme_crash_velocity = roc_20 < -18.0\n    is_capitulation_candidate = is_extreme_crash_velocity and is_deeply_oversold\n\n    # --- 4. Decision Logic (Hierarchical) ---\n\n    # REGIME 1: CONTRARIAN CAPITULATION (HIGHEST PRIORITY)\n    # Buy when there is blood in the streets, but only if momentum shows signs of turning.\n    if is_capitulation_candidate and macd_hist_delta > 0:\n        return "BUY"\n\n    # REGIME 2: CRISIS AVERSION\n    # If in a general crisis (but not a specific capitulation buy signal), be defensive.\n    if is_crisis_regime:\n        if macd_histogram < 0 or current_price < sma_50:\n            return "SELL"\n        return "HOLD" # Hold cash and wait for the storm to pass.\n\n    # REGIME 3: NORMAL MARKET CONDITIONS\n\n    # --- SELL LOGIC (Risk Management First) ---\n    # Priority 1: Dynamic ATR-Based Stop-Loss.\n    # Exit if current price drops 2.5 * ATR below the recent 20-day high.\n    if current_price < (donchian_high_20 - (2.5 * short_atr)):\n        return "SELL"\n\n    # Priority 2: Standard trend breakdown signal.\n    is_primary_downtrend = current_price < sma_50\n    is_momentum_confirming_down = macd_histogram < 0 and prev_macd_histogram >= 0\n    is_sentiment_permissive_for_sell = net_sentiment_score < 1.5 # Tighter sentiment filter\n    if is_primary_downtrend and is_momentum_confirming_down and is_sentiment_permissive_for_sell:\n        return "SELL"\n\n    # Priority 3: Profit-taking on extreme overbought conditions with FADING momentum.\n    is_momentum_fading = macd_hist_delta < 0\n    is_extremely_overbought = rsi > 82\n    if is_extremely_overbought and is_momentum_fading:\n        return "SELL"\n\n    # --- BUY LOGIC ---\n    is_primary_uptrend = current_price > sma_50\n    is_momentum_confirming_up = macd_histogram > 0 and prev_macd_histogram <= 0\n    is_not_overbought = rsi < 78\n    is_sentiment_permissive_for_buy = net_sentiment_score > -1.5 # Tighter sentiment filter\n    is_sufficient_volatility = short_atr > (long_atr * 0.6) # Avoids entering dead, sideways markets.\n\n    if is_primary_uptrend and is_momentum_confirming_up and is_not_overbought and is_sentiment_permissive_for_buy and is_sufficient_volatility:\n        return "BUY"\n\n    # Default action is to hold the current position.\n    return "HOLD"	d46e33438eb393133b739d51806d895e8a388d8b8fdfca19f839707b226601e8	This version implements an ATR-based dynamic stop-loss, replacing the fixed 7% drop, to improve drawdown control and adapt to market volatility as suggested by past lessons. Sentiment analysis is refined by neutralizing "strong jobs report" and tightening permissiveness thresholds (`+/-1.5`) to reduce false signals and allow technicals to dominate more. These changes address the identified weaknesses of high drawdowns in normal regimes and over-reliance on sentiment, while preserving the successful hierarchical regime detection and momentum velocity confirmations.	db86618e-2868-4380-92d7-88f1da2e398e	2026-06-02 00:34:26.562252-04
